import sys, os, csv, json, gzip, io, glob
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
from fractions import Fraction
from decimal import Decimal

UTC = timezone.utc

def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')

def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip()]

def local_to_utc(naive, zone, dst=None):
    """dst: None -> first occurrence; True/False -> choose fold by dst flag."""
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() == b.utcoffset():
        return a.astimezone(UTC)
    if dst is None:
        return a.astimezone(UTC)
    for c in (a, b):
        if bool(c.dst()) == dst:
            return c.astimezone(UTC)
    return a.astimezone(UTC)

def std_offset(zone, naive):
    c = naive.replace(tzinfo=zone)
    return c.utcoffset() - (c.dst() or timedelta(0))

def parse_iso(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d.astimezone(UTC)

def read_site(site, zone, fmt, files):
    out = []  # (id, emp, dir, instant)
    for path in files:
        L = lines_of(path)
        if fmt == 'abbr-csv':
            hdr = None
            for row in csv.reader(L):
                row = [c.strip() for c in row]
                if 'Badge' in row and 'Punch' in row:
                    hdr = row; continue
                if hdr is None: continue
                r = dict(zip(hdr, row))
                d = datetime.strptime(r['Date'], '%m/%d/%Y')
                t = r['Time'].upper()
                ap = None
                if t.endswith('AM') or t.endswith('PM'):
                    ap = t[-2:]; t = t[:-2].strip()
                h, m, s = [int(x) for x in t.split(':')]
                if ap:
                    h = h % 12 + (12 if ap == 'PM' else 0)
                naive = d.replace(hour=h, minute=m, second=s)
                z = r.get('Zone', '').upper()
                dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
                out.append((r['Record'], r['Badge'], r['Punch'].upper(), local_to_utc(naive, zone, dst)))
        elif fmt == 'epoch-jsonl':
            schema = 1
            for l in L:
                o = json.loads(l)
                if 'schema' in o and 'id' not in o and 'punch_id' not in o:
                    schema = o['schema']; continue
                if o.get('heartbeat'): continue
                if schema == 2:
                    pid, emp, dr, ms = o['punch_id'], o['employee'], o['direction'], o['epoch_ms']
                    inst = datetime.fromtimestamp(int(ms) // 1000, UTC)
                else:
                    pid, emp, dr = o['id'], o['emp'], o['dir']
                    if 'ts_ms' in o: inst = datetime.fromtimestamp(int(o['ts_ms']) // 1000, UTC)
                    else: inst = datetime.fromtimestamp(int(o['ts']), UTC)
                out.append((str(pid), emp, dr.upper(), inst))
        elif fmt == 'offset-csv':
            for r in csv.DictReader(L, delimiter=';'):
                ev = r['event'].strip()
                out.append((r['punch_id'], r['employee'], 'IN' if ev == 'clock_in' else 'OUT',
                            parse_iso(r['timestamp'])))
        elif fmt == 'legacy-fixed':
            off = None
            for l in L:
                t = l[0]
                if t == 'H':
                    o = l[13:18].strip()
                    if o and o[0] in '+-' and len(o) == 5:
                        off = (1 if o[0] == '+' else -1) * timedelta(hours=int(o[1:3]), minutes=int(o[3:5]))
                    else:
                        off = None
                elif t == 'D':
                    pid = l[1:9]
                    badge = l[9:15].strip()
                    dr = 'IN' if l[15] == 'I' else 'OUT'
                    naive = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
                    o = off if off is not None else std_offset(zone, naive)
                    inst = (naive - o).replace(tzinfo=UTC)
                    out.append((pid, 'E' + badge, dr, inst))
        elif fmt == 'de-tsv':
            hdr = None
            for l in L:
                row = [c.strip() for c in l.split('\t')]
                if 'Ausweis' in row:
                    hdr = row; continue
                r = dict(zip(hdr, row))
                naive = datetime.strptime(r['Datum'] + ' ' + r['Uhrzeit'], '%d.%m.%Y %H:%M')
                z = r.get('Zeitzone', '').upper()
                dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
                out.append((r['Nr'], r['Ausweis'], 'IN' if r['Buchung'] == 'K' else 'OUT',
                            local_to_utc(naive, zone, dst)))
        elif fmt == 'local-csv':
            for r in csv.DictReader(L):
                naive = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
                out.append((r['punch_ref'], r['employee_id'], r['direction'].strip().upper(),
                            local_to_utc(naive, zone)))
        elif fmt == 'local-jsonl':
            for l in L:
                o = json.loads(l)
                p = o['punch']
                naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
                out.append((str(p['id']), p['badge'], p['type'].upper(), local_to_utc(naive, zone)))
        else:
            raise ValueError(fmt)
    return out

def rnd(inst, zone):
    loc = inst.astimezone(zone)
    secs = loc.hour * 3600 + loc.minute * 60 + loc.second
    r = ((secs + 180) // 360) * 360
    return inst + timedelta(seconds=r - secs - 0)  # microseconds are zero

def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start']); pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])
    sites = {}
    for r in csv.DictReader(lines_of(os.path.join(inp, 'sites.csv'))):
        sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = {}
    for r in csv.DictReader(lines_of(os.path.join(inp, 'employees.csv'))):
        emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in csv.DictReader(lines_of(os.path.join(inp, 'rates.csv'))):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values(): v.sort()

    punches = {}  # (site,id) -> [emp, dir, inst]
    ever = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        files = sorted(p for p in glob.glob(os.path.join(d, '**', '*'), recursive=True) if os.path.isfile(p))
        for pid, emp, dr, inst in read_site(site, zone, fmt, files):
            k = (site, pid)
            ever.add(k)
            if k not in punches:
                punches[k] = [emp.strip(), dr, inst]
    # corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    for p in sorted(glob.glob(os.path.join(cdir, '**', '*'), recursive=True)):
        if os.path.isfile(p):
            corr.extend(csv.DictReader(lines_of(p)))
    corr = [c for c in corr if parse_iso(c['issued_at']) <= cutoff]
    corr.sort(key=lambda c: (parse_iso(c['issued_at']), c['correction_id']))
    applied = 0
    voided = set()
    for c in corr:
        k = (c['site'].strip(), c['punch_id'].strip())
        a = c['action'].strip()
        if a == 'void':
            if k in punches:
                del punches[k]; voided.add(k); applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = parse_iso(c['time']); applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [c['employee'].strip(), c['type'].strip().upper(), parse_iso(c['time'])]
                applied += 1
    byemp = {}
    for (site, pid), (emp, dr, inst) in punches.items():
        if emp in emps:
            byemp.setdefault(emp, []).append((inst, 0 if dr == 'OUT' else 1, site, pid, dr))
    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, pay=Fraction(0)) for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0)
    for emp, lst in byemp.items():
        home = sites[emps[emp]][0]
        lst.sort(key=lambda x: x[:4])
        kept = []
        last = None
        def wd(inst, site):
            return rnd(inst, sites[site][0]).astimezone(home).date()
        for inst, _, site, pid, dr in lst:
            if last is not None and last[4] == dr and (inst - last[0]).total_seconds() <= 300:
                if pstart <= wd(inst, site) <= pend: exc['duplicates_dropped'] += 1
                continue
            last = (inst, 0, site, pid, dr)
            kept.append((rnd(inst, sites[site][0]), site, dr))
        shifts = []
        pend_in = None
        def inperiod(p): return pstart <= p[0].astimezone(home).date() <= pend
        for p in kept:
            if p[2] == 'IN':
                if pend_in is not None and inperiod(pend_in): exc['open_shifts'] += 1
                pend_in = p
            else:
                if pend_in is not None and (p[0] - pend_in[0]) <= timedelta(hours=16):
                    shifts.append((pend_in, p)); pend_in = None
                else:
                    if pend_in is not None and inperiod(pend_in): exc['open_shifts'] += 1
                    pend_in = None
                    if inperiod(p): exc['orphan_outs'] += 1
        if pend_in is not None and inperiod(pend_in): exc['open_shifts'] += 1
        items = []
        for i, o in shifts:
            w = i[0].astimezone(home).date()
            if not (pstart <= w <= pend): continue
            worked = max(0, int((o[0] - i[0]).total_seconds() // 60))
            paid = worked - 30 if worked > 360 else worked
            zone = sites[i[1]][0]
            night = 0
            for m in range(worked):
                h = (i[0] + timedelta(minutes=m)).astimezone(zone).hour
                if h >= 22 or h < 6: night += 1
            night = min(night, paid)
            items.append((i[0], w, paid, night))
        items.sort()
        daily = {}; week = {}
        for inst, w, paid, night in items:
            used = daily.get(w, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daily[w] = used + paid
            wk = w - timedelta(days=w.weekday())
            wu = week.get(wk, 0)
            nd = paid - dot
            wot = max(0, wu + nd - 2400) - max(0, wu - 2400)
            week[wk] = wu + nd
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, rt in rates.get(emp, []):
                if ef <= w: rate = rt
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            r = res[emp]
            r['shifts'] += 1; r['paid_minutes'] += paid; r['overtime_minutes'] += ot
            r['night_minutes'] += night; r['pay'] += pay
    def money(f):
        c = (f * 100 + Fraction(1, 2)).__floor__()
        return '%d.%02d' % (c // 100, c % 100)
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    outemps = {}
    for e, r in res.items():
        g = money(r['pay'])
        totc += int(g.replace('.', ''))
        d = {k: r[k] for k in tot}
        for k in tot: tot[k] += r[k]
        d['gross'] = g
        outemps[e] = d
    tot['gross'] = '%d.%02d' % (totc // 100, totc % 100)
    exc['corrections_applied'] = applied
    with open(outp, 'w') as f:
        json.dump(dict(period=dict(start=period['start'], end=period['end']), employees=outemps,
                       exceptions=exc, totals=tot), f, indent=1)

if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
